const std = @import("std");
const Allocator = std.mem.Allocator;
const Sha256 = std.crypto.hash.sha2.Sha256;
const Mutex = std.Thread.Mutex;

pub const CPFPEGConfig = struct {
    pub const DIGEST_SIZE: usize = Sha256.digest_length;
    pub const MAX_BLOCK_SIZE: usize = 1048576;
    pub const MAX_TENSION: f64 = 0.95;
    pub const TENSION_THRESHOLD: f64 = 0.5;
    pub const TENSION_DECAY: f64 = 0.1;
};

pub const Digest = [CPFPEGConfig.DIGEST_SIZE]u8;

pub const PolarityState = enum(u8) {
    open_cardinal = 0,
    defensive_instinct = 1,
    focal_tension = 2,
};

pub const MemoryBlock = struct {
    data: []const u8,
    polarity: PolarityState,
    tension: f64,

    pub fn deinit(self: *MemoryBlock, allocator: Allocator) void {
        allocator.free(self.data);
        self.data = &[_]u8{};
        self.tension = 0.0;
    }
};

const DigestContext = struct {
    pub fn hash(_: @This(), key: Digest) u64 {
        var result: u64 = 0;
        @memcpy(std.mem.asBytes(&result), key[0..8]);
        return result;
    }

    pub fn eql(_: @This(), a: Digest, b: Digest) bool {
        return std.mem.eql(u8, &a, &b);
    }
};

pub const RegistrationResult = enum {
    inserted,
    replaced,
};

pub const ExtractError = error{
    BlockNotFound,
    WrongPolarity,
    OutOfMemory,
};

pub const FocalPointRegulator = struct {
    blocks: std.HashMap(Digest, MemoryBlock, DigestContext, std.hash_map.default_max_load_percentage),
    allocator: Allocator,
    mutex: Mutex,

    pub fn init(allocator: Allocator) FocalPointRegulator {
        return FocalPointRegulator{
            .blocks = std.HashMap(Digest, MemoryBlock, DigestContext, std.hash_map.default_max_load_percentage).init(allocator),
            .allocator = allocator,
            .mutex = Mutex{},
        };
    }

    pub fn deinit(self: *FocalPointRegulator) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        var iter = self.blocks.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.blocks.deinit();
        self.blocks = undefined;
    }

    pub fn registerTension(self: *FocalPointRegulator, data: []const u8) !struct { digest: Digest, result: RegistrationResult } {
        if (data.len > CPFPEGConfig.MAX_BLOCK_SIZE) return error.BlockTooLarge;

        const duplicated_data = try self.allocator.dupe(u8, data);
        errdefer self.allocator.free(duplicated_data);

        var digest: Digest = undefined;
        Sha256.hash(duplicated_data, &digest, .{});

        self.mutex.lock();
        defer self.mutex.unlock();

        var tension_val = CPFPEGConfig.MAX_TENSION;
        if (std.math.isNan(tension_val)) tension_val = 0.0;
        tension_val = std.math.clamp(tension_val, 0.0, CPFPEGConfig.MAX_TENSION);

        const new_block = MemoryBlock{
            .data = duplicated_data,
            .polarity = .open_cardinal,
            .tension = tension_val,
        };

        if (self.blocks.fetchRemove(digest)) |kv| {
            var old_block = kv.value;
            old_block.deinit(self.allocator);
            try self.blocks.put(digest, new_block);
            return .{ .digest = digest, .result = .replaced };
        } else {
            try self.blocks.put(digest, new_block);
            return .{ .digest = digest, .result = .inserted };
        }
    }

    pub fn removeBlock(self: *FocalPointRegulator, digest: Digest) bool {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.blocks.fetchRemove(digest)) |kv| {
            var block = kv.value;
            block.deinit(self.allocator);
            return true;
        }
        return false;
    }

    pub fn stabilizeIdeologicalTension(self: *FocalPointRegulator, digest: Digest) bool {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.blocks.getPtr(digest)) |block| {
            if (block.polarity != .open_cardinal) return true;

            if (std.math.isNan(block.tension)) block.tension = 0.0;
            block.tension = std.math.clamp(block.tension, 0.0, CPFPEGConfig.MAX_TENSION);

            if (block.tension > CPFPEGConfig.TENSION_THRESHOLD) {
                block.polarity = .defensive_instinct;
                block.tension = std.math.clamp(block.tension * CPFPEGConfig.TENSION_DECAY, 0.0, CPFPEGConfig.MAX_TENSION);
            } else {
                block.polarity = .focal_tension;
            }
            return true;
        }
        return false;
    }

    pub fn extractStructuralOutput(self: *const FocalPointRegulator, digest: Digest, out_allocator: Allocator) ExtractError![]const u8 {
        var mutable_self = @constCast(self);
        mutable_self.mutex.lock();
        defer mutable_self.mutex.unlock();

        if (self.blocks.get(digest)) |block| {
            if (block.polarity == .defensive_instinct) {
