const std = @import("std");
const Allocator = std.mem.Allocator;
const Mutex = std.Thread.Mutex;
const Sha256 = std.crypto.hash.sha2.Sha256;

pub const NSIRConfig = struct {
    pub const DIGEST_SIZE: usize = Sha256.digest_length;
    pub const MAX_NODES: usize = 1048576;
    pub const QUANTUM_TENSION_LIMIT: f64 = 0.95;
};

pub const Digest = [NSIRConfig.DIGEST_SIZE]u8;

pub const Complex = struct {
    re: f64,
    im: f64,

    pub fn init(re: f64, im: f64) Complex {
        return .{ .re = re, .im = im };
    }

    pub fn magSq(self: Complex) f64 {
        return self.re * self.re + self.im * self.im;
    }

    pub fn add(self: Complex, other: Complex) Complex {
        return .{ .re = self.re + other.re, .im = self.im + other.im };
    }

    pub fn mul(self: Complex, other: Complex) Complex {
        return .{
            .re = self.re * other.re - self.im * other.im,
            .im = self.re * other.im + self.im * other.re,
        };
    }
};

pub const Qubit = struct {
    alpha: Complex,
    beta: Complex,

    pub fn init(alpha: Complex, beta: Complex) Qubit {
        return .{ .alpha = alpha, .beta = beta };
    }

    pub fn normSquared(self: Qubit) f64 {
        return self.alpha.magSq() + self.beta.magSq();
    }

    pub fn normalize(self: *Qubit) void {
        const norm = std.math.sqrt(self.normSquared());
        if (norm > 0.0) {
            self.alpha.re /= norm;
            self.alpha.im /= norm;
            self.beta.re /= norm;
            self.beta.im /= norm;
        }
    }
};

