    weight: f64,
};

const DigestContext = struct {
    pub fn hash(_: @This(), key: Digest) u64 {
        var result: u64 = 0;
        @memcpy(std.mem.asBytes(&result), key[0..8]);
        return result;
    }

    pub fn eql(_: @This(), a: Digest, b: Digest) bool {
        return std.mem.eql(u8, &a, &b);
    }
};

pub const NSIRError = error{
    NodeNotFound,
    NodeTooLarge,
    GraphFull,
    OutOfMemory,
    EdgeInvalid,
};

pub const SelfSimilarRelationalGraph = struct {
    nodes: std.HashMap(Digest, Node, DigestContext, std.hash_map.default_max_load_percentage),
    edges: std.ArrayList(Edge),
    allocator: Allocator,
    mutex: Mutex,

    pub fn init(allocator: Allocator) SelfSimilarRelationalGraph {
        return SelfSimilarRelationalGraph{
            .nodes = std.HashMap(Digest, Node, DigestContext, std.hash_map.default_max_load_percentage).init(allocator),
            .edges = std.ArrayList(Edge).init(allocator),
            .allocator = allocator,
            .mutex = Mutex{},
        };
    }

    pub fn deinit(self: *SelfSimilarRelationalGraph) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        var iter = self.nodes.iterator();
        while (iter.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.nodes.deinit();
        self.edges.deinit();
        self.nodes = undefined;
        self.edges = undefined;
    }

    pub fn addNode(self: *SelfSimilarRelationalGraph, data: []const u8) NSIRError!Digest {
        if (data.len > 1048576) return error.NodeTooLarge;

        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.nodes.count() >= NSIRConfig.MAX_NODES) return error.GraphFull;

        const duplicated_data = try self.allocator.dupe(u8, data);
        errdefer self.allocator.free(duplicated_data);

        var digest: Digest = undefined;
        Sha256.hash(duplicated_data, &digest, .{});

        var q = Qubit.init(Complex.init(1.0, 0.0), Complex.init(0.0, 0.0));
        q.normalize();

        const new_node = Node{
            .id = digest,
            .state = q,
            .data = duplicated_data,
        };

        if (self.nodes.fetchRemove(digest)) |kv| {
            var old_node = kv.value;
            old_node.deinit(self.allocator);
        }

        try self.nodes.put(digest, new_node);
        return digest;
    }

    pub fn addEdge(self: *SelfSimilarRelationalGraph, source: Digest, target: Digest, quality: EdgeQuality, weight: f64) NSIRError!void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (!self.nodes.contains(source) or !self.nodes.contains(target)) {
            return error.NodeNotFound;
        }

        const valid_weight = std.math.clamp(if (std.math.isNan(weight)) 0.0 else weight, 0.0, 1.0);

        try self.edges.append(Edge{
            .source_id = source,
            .target_id = target,
            .quality = quality,
            .weight = valid_weight,
        });
    }

    pub fn applyHadamardGate(self: *SelfSimilarRelationalGraph, node_id: Digest) NSIRError!void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.nodes.getPtr(node_id)) |node| {
            const inv_sqrt2 = 1.0 / std.math.sqrt(2.0);
            const a = node.state.alpha;
            const b = node.state.beta;

            node.state.alpha = Complex.init((a.re + b.re) * inv_sqrt2, (a.im + b.im) * inv_sqrt2);
            node.state.beta = Complex.init((a.re - b.re) * inv_sqrt2, (a.im - b.im) * inv_sqrt2);
            node.state.normalize();
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn collapseNode(self: *SelfSimilarRelationalGraph, node_id: Digest) NSIRError!void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.nodes.getPtr(node_id)) |node| {
            if (node.state.alpha.magSq() >= node.state.beta.magSq()) {
                node.state.alpha = Complex.init(1.0, 0.0);
                node.state.beta = Complex.init(0.0, 0.0);
            } else {
                node.state.alpha = Complex.init(0.0, 0.0);
                node.state.beta = Complex.init(1.0, 0.0);
            }
        } else {
            return error.NodeNotFound;
        }
    }

    pub fn extractConcept(self: *const SelfSimilarRelationalGraph, node_id: Digest, out_allocator: Allocator) NSIRError![]const u8 {
        var mutable_self = @constCast(self);
        mutable_self.mutex.lock();
        defer mutable_self.mutex.unlock();

        if (self.nodes.get(node_id)) |node| {
            if (out_allocator.dupe(u8, node.data)) |copied| {
                return copied;
            } else |_| {
                return error.OutOfMemory;
            }
        }
        return error.NodeNotFound;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        const check = gpa.deinit();
        if (check == .leak) @panic("Memory leak detected");
    }
    const allocator = gpa.allocator();

    var graph = SelfSimilarRelationalGraph.init(allocator);
    defer graph.deinit();

    const node_data_1 = "root_ideology_alpha";
    const node_data_2 = "relational_tension_beta";

    const id1 = try graph.addNode(node_data_1);
    const id2 = try graph.addNode(node_data_2);

    try graph.addEdge(id1, id2, .superposition, 0.85);

    try graph.applyHadamardGate(id1);
    try graph.collapseNode(id1);

    if (graph.extractConcept(id1, allocator)) |output| {
        defer allocator.free(output);
        if (!std.mem.eql(u8, output, node_data_1)) {
            return error.EdgeInvalid;
        }
    } else |err| {
        return err;
    }
}
